INSERT INTO public.sentence_translations (id, sentence_id, target_language_code, text, source_record_id, created_at) SELECT 'bc86b64f-82ca-535c-99ab-fe821a02f752', '71f85c78-ca29-5de1-b055-e89dc130e885', 'vi', 'Các thành viên trong nhóm cũng có thể theo dõi các quyết định và hạn chót trong một tài liệu dùng chung.', '46349bf6-5bd5-569b-95d0-e6718afc2588', '2026-10-15T00:00:00Z' WHERE NOT EXISTS (SELECT 1 FROM public.content_segments cs JOIN public.content_items ci ON ci.id = cs.content_id WHERE cs.sentence_id = '71f85c78-ca29-5de1-b055-e89dc130e885' AND ci.publication_status = 'published') ON CONFLICT (sentence_id, target_language_code, source_record_id) DO NOTHING;
INSERT INTO public.sentence_translations (id, sentence_id, target_language_code, text, source_record_id, created_at) SELECT 'bce76f48-5d2d-59e0-b9b2-9c475fae1350', 'ca3f4b7f-ec95-5064-9e91-f0e44e0d620a', 'vi', 'Kết quả là, thói quen đáng tin cậy này giúp xây dựng niềm tin bền vững trong toàn bộ tổ chức.', '46349bf6-5bd5-569b-95d0-e6718afc2588', '2026-10-15T00:00:00Z' WHERE NOT EXISTS (SELECT 1 FROM public.content_segments cs JOIN public.content_items ci ON ci.id = cs.content_id WHERE cs.sentence_id = 'ca3f4b7f-ec95-5064-9e91-f0e44e0d620a' AND ci.publication_status = 'published') ON CONFLICT (sentence_id, target_language_code, source_record_id) DO NOTHING;
INSERT INTO public.sentence_translations (id, sentence_id, target_language_code, text, source_record_id, created_at) SELECT 'ff021d91-992d-5b49-ae81-abf5439fd9f8', '89347a0f-cc8d-514d-94ff-2dc3d4ff057e', 'vi', 'Các công cụ trực tuyến giúp việc học và làm việc linh hoạt hơn, nhưng nhìn vào màn hình suốt buổi tối có thể ảnh hưởng xấu đến giấc ngủ của bạn.', 'b4639cec-dd9c-538c-85e1-255c30b8c015', '2026-10-15T00:00:00Z' WHERE NOT EXISTS (SELECT 1 FROM public.content_segments cs JOIN public.content_items ci ON ci.id = cs.content_id WHERE cs.sentence_id = '89347a0f-cc8d-514d-94ff-2dc3d4ff057e' AND ci.publication_status = 'published') ON CONFLICT (sentence_id, target_language_code, source_record_id) DO NOTHING;
