INSERT INTO public.sentence_translations (id, sentence_id, target_language_code, text, source_record_id, created_at) SELECT '5a4f691d-3740-50fb-acec-ffab3cc11df2', '9ff09055-dffd-5154-ac55-2778487e90fc', 'vi', 'Trước khi đi ngủ, anh dành hai mươi phút đọc sách giấy hoặc xem lại các ghi chú nhẹ nhàng.', 'b4639cec-dd9c-538c-85e1-255c30b8c015', '2026-10-15T00:00:00Z' WHERE NOT EXISTS (SELECT 1 FROM public.content_segments cs JOIN public.content_items ci ON ci.id = cs.content_id WHERE cs.sentence_id = '9ff09055-dffd-5154-ac55-2778487e90fc' AND ci.publication_status = 'published') ON CONFLICT (sentence_id, target_language_code, source_record_id) DO NOTHING;
