INSERT INTO public.sentence_translations (id, sentence_id, target_language_code, text, source_record_id, created_at) SELECT '4a3445ac-c492-5214-8c71-8af93d419478', '7138746c-b1a8-5db6-b02b-6ef0ca668f91', 'vi', 'Sau ba tuần, Quang nhận thấy trí nhớ và sự tập trung buổi sáng của mình đã cải thiện rõ rệt.', 'b4639cec-dd9c-538c-85e1-255c30b8c015', '2026-10-15T00:00:00Z' WHERE NOT EXISTS (SELECT 1 FROM public.content_segments cs JOIN public.content_items ci ON ci.id = cs.content_id WHERE cs.sentence_id = '7138746c-b1a8-5db6-b02b-6ef0ca668f91' AND ci.publication_status = 'published') ON CONFLICT (sentence_id, target_language_code, source_record_id) DO NOTHING;
